        .feature-card:hover {
            transform: translateY(-5px);
            box-shadow: var(--shadow);
        }

        .feature-icon {
            font-size: 2rem;
            margin-bottom: 20px;
            color: var(--primary-color);
        }

        .feature-card h3 {
            margin-bottom: 10px;
            font-size: 1.25rem;
        }

        .feature-card p {
            color: var(--text-gray);
            font-size: 0.95rem;
        }

        /* Popular Courses */
        .popular-courses {
            padding: 80px 0;
            background-color: var(--bg-light);
        }

        .course-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 25px;
        }

        .course-card {
            background: var(--white);
            border-radius: var(--border-radius);
            overflow: hidden;
            box-shadow: 0 1px 2px rgba(0,0,0,0.05);
            transition: box-shadow 0.3s;
            display: flex;
            flex-direction: column;
        }

        .course-card:hover {
            box-shadow: var(--shadow);
        }

        .course-img {
            height: 160px;
            background-color: #e5e7eb;
            object-fit: cover;
            width: 100%;
        }

        .course-content {
            padding: 20px;
            flex: 1;
            display: flex;
            flex-direction: column;
        }

        .course-tag {
            font-size: 0.75rem;
            color: var(--primary-color);
            background: #eff6ff;
            padding: 2px 8px;
            border-radius: 4px;
            align-self: flex-start;
            margin-bottom: 10px;
            font-weight: 600;
        }

        .course-title {
            font-size: 1.1rem;
            font-weight: 600;
            margin-bottom: 10px;
            line-height: 1.4;
        }

        .course-desc {
            font-size: 0.9rem;
            color: var(--text-gray);
            margin-bottom: 20px;
            flex: 1;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .course-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid #e5e7eb;
            padding-top: 15px;
            margin-top: auto;
        }

        .course-price {
            font-weight: 700;
            color: var(--text-dark);
            font-size: 1.1rem;
        }

        .course-meta {
            font-size: 0.8rem;
            color: var(--text-gray);
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* Footer */
        footer {
            background-color: var(--text-dark);
            color: var(--white);
            padding: 60px 0 20px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 3fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-brand p {
            color: #9ca3af;
            margin-top: 15px;
            font-size: 0.9rem;
            max-width: 300px;
        }

        .footer-col h4 {
            font-size: 1rem;
            margin-bottom: 20px;
            color: var(--white);
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col a {
            color: #9ca3af;
            font-size: 0.9rem;
        }

        .footer-col a:hover {
            color: var(--white);
        }

        .footer-bottom {
            border-top: 1px solid #374151;
            padding-top: 20px;
            text-align: center;
            color: #9ca3af;
            font-size: 0.85rem;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .stats-grid, .feature-grid, .course-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 768px) {
            .nav-links {
                display: none; /* Simplified for mobile */
            }
            .hero h1 {
                font-size: 2rem;
            }
